--
-- Table structure for table `bk_psychological_test_results`
--

DROP TABLE IF EXISTS `bk_psychological_test_results`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bk_psychological_test_results` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `test_id` bigint unsigned NOT NULL,
  `student_id` bigint unsigned NOT NULL,
  `taken_at` timestamp NOT NULL,
  `answers` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `dimension_scores` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `dominant_dimension` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `secondary_dimension` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tertiary_dimension` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `holland_code` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `profile_label` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `analysis_summary` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `item_analysis` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `career_recommendations` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `study_recommendations` text COLLATE utf8mb4_unicode_ci,
  `action_plan` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `scientific_sources` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `ai_report` json DEFAULT NULL,
  `ai_provider` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ai_model` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `priority_level` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `priority_label` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `executive_summary` text COLLATE utf8mb4_unicode_ci,
  `counselor_notes` text COLLATE utf8mb4_unicode_ci,
  `status` enum('SUBMITTED','VERIFIED_BY_BK') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'SUBMITTED',
  `ai_analyzed_at` timestamp NULL DEFAULT NULL,
  `verified_by` bigint unsigned DEFAULT NULL,
  `verified_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `bk_psychological_test_results_test_id_foreign` (`test_id`),
  KEY `bk_psychological_test_results_verified_by_foreign` (`verified_by`),
  KEY `bk_psychological_test_results_student_id_test_id_index` (`student_id`,`test_id`),
  KEY `bk_psychological_test_results_dominant_dimension_index` (`dominant_dimension`),
  CONSTRAINT `bk_psychological_test_results_student_id_foreign` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE CASCADE,
  CONSTRAINT `bk_psychological_test_results_test_id_foreign` FOREIGN KEY (`test_id`) REFERENCES `bk_psychological_tests` (`id`) ON DELETE CASCADE,
  CONSTRAINT `bk_psychological_test_results_verified_by_foreign` FOREIGN KEY (`verified_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `bk_psychological_test_results_chk_1` CHECK (json_valid(`answers`)),
  CONSTRAINT `bk_psychological_test_results_chk_2` CHECK (json_valid(`dimension_scores`)),
  CONSTRAINT `bk_psychological_test_results_chk_3` CHECK (json_valid(`item_analysis`)),
  CONSTRAINT `bk_psychological_test_results_chk_4` CHECK (json_valid(`career_recommendations`)),
  CONSTRAINT `bk_psychological_test_results_chk_5` CHECK (json_valid(`action_plan`)),
  CONSTRAINT `bk_psychological_test_results_chk_6` CHECK (json_valid(`scientific_sources`))
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

