--
-- Table structure for table `extracurricular_attendances`
--

DROP TABLE IF EXISTS `extracurricular_attendances`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `extracurricular_attendances` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `extracurricular_id` bigint unsigned NOT NULL,
  `student_id` bigint unsigned NOT NULL,
  `class_id` bigint unsigned DEFAULT NULL,
  `date` date NOT NULL,
  `time` time NOT NULL,
  `status` enum('HADIR','TERLAMBAT','IZIN','SAKIT','ALPA') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'HADIR',
  `method` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MANUAL',
  `device_info` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `latitude` decimal(10,7) DEFAULT NULL,
  `longitude` decimal(10,7) DEFAULT NULL,
  `selfie_path` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `recorded_by` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `extra_att_unique` (`extracurricular_id`,`student_id`,`date`),
  KEY `extracurricular_attendances_class_id_foreign` (`class_id`),
  KEY `extracurricular_attendances_recorded_by_foreign` (`recorded_by`),
  KEY `extracurricular_attendances_extracurricular_id_date_index` (`extracurricular_id`,`date`),
  KEY `extracurricular_attendances_student_id_date_index` (`student_id`,`date`),
  CONSTRAINT `extracurricular_attendances_class_id_foreign` FOREIGN KEY (`class_id`) REFERENCES `school_classes` (`id`) ON DELETE SET NULL,
  CONSTRAINT `extracurricular_attendances_extracurricular_id_foreign` FOREIGN KEY (`extracurricular_id`) REFERENCES `extracurriculars` (`id`) ON DELETE CASCADE,
  CONSTRAINT `extracurricular_attendances_recorded_by_foreign` FOREIGN KEY (`recorded_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `extracurricular_attendances_student_id_foreign` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

