  `expedition_number` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `outgoing_letter_id` bigint unsigned DEFAULT NULL,
  `letter_number` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `letter_date` date NOT NULL,
  `delivery_date` date NOT NULL,
  `recipient_name` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `destination_type` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Internal',
  `subject` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `courier_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `receiver_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `receipt_status` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Terkirim',
  `received_at` datetime DEFAULT NULL,
  `receipt_file_path` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `letter_expeditions_expedition_number_unique` (`expedition_number`),
  KEY `letter_expeditions_outgoing_letter_id_foreign` (`outgoing_letter_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
