INSERT INTO `school_bells` VALUES (43,'Murottal Pagi Pra-KBM (Senin)','06:05','[\"Senin\"]','murottal','https://cdn.islamic.network/quran/audio-surah/128/ar.alafasy/55.mp3',55,'Ar-Rahman, Al-Waqi\'ah','[55,56]',NULL,NULL,85,1200,'Murottal Al-Qur\'an 20 menit (Surah Ar-Rahman & Al-Waqi\'ah) mengawali awal pekan dengan penuh rasa syukur dan berkah','Selamat pagi civitas akademika SMAN 1 Lengkong. Mengawali pagi awal pekan dengan penuh rasa syukur dan berkah, mari bersama kita dengarkan lantunan Murottal Al-Qur\'an.',1,1,'2026-11-13 06:58:37','2026-11-15 17:32:11'),(44,'Murottal Pagi Pra-KBM (Selasa)','06:05','[\"Selasa\"]','murottal','https://cdn.islamic.network/quran/audio-surah/128/ar.alafasy/36.mp3',36,'Yasin','[36]',NULL,NULL,85,1200,'Murottal Al-Qur\'an 20 menit Surah Yasin (Qalbul Qur\'an) menentramkan jiwa sebelum Senam Indonesia Hebat','Selamat pagi civitas akademika SMAN 1 Lengkong. Mengawali pagi hari Selasa yang penuh semangat, mari bersama kita dengarkan lantunan Murottal Al-Qur\'an Surah Yasin.',1,2,'2026-11-13 06:58:37','2026-11-15 17:32:11'),(45,'Murottal Pagi Pra-KBM (Rabu)','06:05','[\"Rabu\"]','murottal','https://cdn.islamic.network/quran/audio-surah/128/ar.alafasy/67.mp3',67,'Al-Mulk, As-Sajdah, Al-Insan','[67,32,76]',NULL,NULL,85,1200,'Murottal Al-Qur\'an 20 menit (Surah Al-Mulk, As-Sajdah & Al-Insan) mengiringi persiapan literasi hafalan Qur\'an','Selamat pagi civitas akademika SMAN 1 Lengkong. Mengawali pagi hari Rabu bersama bimbingan Wali Kelas dan literasi Al-Qur\'an, mari bersama kita dengarkan lantunan Murottal Al-Qur\'an.',1,3,'2026-11-13 06:58:37','2026-11-15 17:32:11'),(46,'Murottal Pagi Pra-KBM (Kamis)','06:05','[\"Kamis\"]','murottal','https://cdn.islamic.network/quran/audio-surah/128/ar.alafasy/19.mp3',19,'Maryam, Al-Insan','[19,76]',NULL,NULL,85,1200,'Murottal Al-Qur\'an 20 menit (Surah Maryam & Al-Insan) menyejukkan hati sebelum Shalat Dhuha bersama','Selamat pagi civitas akademika SMAN 1 Lengkong. Mengawali pagi hari Kamis sebelum p