DROP TABLE IF EXISTS `student_ai_raports`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `student_ai_raports` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `student_id` bigint unsigned NOT NULL,
  `academic_year_id` bigint unsigned DEFAULT NULL,
  `generated_at` timestamp NOT NULL,
  `generated_by` bigint unsigned DEFAULT NULL,
  `generation_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MANUAL',
  `attendance_rate` decimal(5,2) NOT NULL DEFAULT '0.00',
  `attendance_total` int unsigned NOT NULL DEFAULT '0',
  `attendance_present` int unsigned NOT NULL DEFAULT '0',
  `attendance_late` int unsigned NOT NULL DEFAULT '0',
  `attendance_permit` int unsigned NOT NULL DEFAULT '0',
  `attendance_sick` int unsigned NOT NULL DEFAULT '0',
  `attendance_alpha` int unsigned NOT NULL DEFAULT '0',
  `achievement_points` int unsigned NOT NULL DEFAULT '0',
  `achievement_count` int unsigned NOT NULL DEFAULT '0',
  `reward_tier` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `violation_points` int unsigned NOT NULL DEFAULT '0',
  `violation_count` int unsigned NOT NULL DEFAULT '0',
  `guidance_tier` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `habit_score` decimal(5,2) NOT NULL DEFAULT '0.00',
  `habit_status` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `habit_total_logs` int unsigned NOT NULL DEFAULT '0',
  `habit_completed_logs` int unsigned NOT NULL DEFAULT '0',
  `worship_dzuhur_total` int unsigned NOT NULL DEFAULT '0',
  `worship_dzuhur_hadir` int unsigned NOT NULL DEFAULT '0',
  `worship_dzuhur_rate` decimal(5,2) NOT NULL DEFAULT '0.00',
  `worship_dhuha_total` int unsigned NOT NULL DEFAULT '0',
  `worship_dhuha_hadir` int unsigned NOT NULL DEFAULT '0',
  `worship_dhuha_rate` decimal(5,2) NOT NULL DEFAULT '0.00',
  `worship_keputrian_total` int unsigned NOT NULL DEFAULT '0',
  `worship_keputrian_hadir` int unsigned NOT NULL DEFAULT '0',
  `worship_keputrian_rate` decimal(5,2) NOT NULL DEFAULT '0.00',
  `extracurricular_rate` decimal(5,2) NOT NULL DEFAULT '0.00',
  `extracurricular_notes` text COLLATE utf8mb4_unicode_ci,
  `is_female` tinyint(1) NOT NULL DEFAULT '0',
  `tahfidz_completed_count` int unsigned NOT NULL DEFAULT '0',
  `tahfidz_target_count` int unsigned NOT NULL DEFAULT '37',
  `tahfidz_progress_pct` decimal(5,2) NOT NULL DEFAULT '0.00',
  `tahfidz_status` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `avg_makhraj` decimal(3,1) DEFAULT NULL,
  `avg_tajwid` decimal(3,1) DEFAULT NULL,
  `avg_kelancaran` decimal(3,1) DEFAULT NULL,
  `development_index` decimal(5,2) NOT NULL DEFAULT '0.00',
  `ringkasan_komprehensif` text COLLATE utf8mb4_unicode_ci,
  `catatan_profil_pelajar` text COLLATE utf8mb4_unicode_ci,
  `penilaian_siswa` text COLLATE utf8mb4_unicode_ci,
  `perkembangan` text COLLATE utf8mb4_unicode_ci,
  `analisis_masalah` text COLLATE utf8mb4_unicode_ci,
  `pemecahan_masalah` text COLLATE utf8mb4_unicode_ci,
  `rekomendasi` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `context_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `provider` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `model` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_ai_generated` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `student_ai_raports_student_id_unique` (`student_id`),
  KEY `student_ai_raports_academic_year_id_foreign` (`academic_year_id`),
  KEY `student_ai_raports_generated_by_foreign` (`generated_by`),
  CONSTRAINT `student_ai_raports_academic_year_id_foreign` FOREIGN KEY (`academic_year_id`) REFERENCES `academic_years` (`id`) ON DELETE SET NULL,
  CONSTRAINT `student_ai_raports_generated_by_foreign` FOREIGN KEY (`generated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `student_ai_raports_student_id_foreign` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=132 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
