_keagamaan\":{\"role\":\"Koordinator Keagamaan & Pembina Tahfidz\",\"actions\":[\"Jadwalkan pendampingan setoran hafalan Juz 30 secara rutin minimal 2 kali seminggu untuk memantau tajwid dan makhraj.\",\"Berikan bimbingan personal terkait keutamaan dan konsistensi mengikuti shalat dhuha serta shalat berjamaah di musholla\\/masjid sekolah.\"]},\"bk\":{\"role\":\"Guru Bimbingan Konseling (BK)\",\"actions\":[\"Lakukan sesi konseling suportif berkala untuk memetakan rencana studi lanjut dan minat karier.\",\"Dukung siswa dalam mengembangkan strategi adaptasi belajar yang seimbang.\"]},\"orang_tua\":{\"role\":\"Orang Tua \\/ Wali\",\"actions\":[\"Pertahankan suasana rumah yang kondusif bagi amalan ibadah dan belajar mandiri.\",\"Ajak anak membiasakan tilawah Al-Qur\'an bersama keluarga untuk memupuk kecintaan pada kalam Ilahi.\",\"Luangkan waktu 10-15 menit setiap hari untuk mendengarkan refleksi aktivitas anak di sekolah.\"]},\"siswa\":{\"role\":\"Siswa (Refleksi Diri)\",\"actions\":[\"Pertahankan kebiasaan baik yang sudah konsisten dan jadikan sebagai inspirasi bagi teman sebaya.\",\"Tingkatkan rutinitas murajaah hafalan Juz 30 dan disiplin mengikuti shalat dhuha serta dzuhur berjamaah tepat waktu.\"]},\"manajemen\":{\"role\":\"Kepala Sekolah & Manajemen\",\"actions\":[\"Pantau ketersediaan sarana dan dukungan program pengembangan minat bakat siswa secara berkelanjutan.\",\"Dukung sarana musholla sekolah dan pengadaan sertifikat tahfidz Al-Qur\'an bagi siswa yang menyelesaikan Juz 30.\",\"Dukung penguatan budaya positif sekolah dan sinergi kemitraan tri sentra pendidikan (Sekolah, Keluarga, Masyarakat).\"]}}','{\"attendance_score\":0,\"discipline_score\":92.5,\"achievement_score\":0,\"worship_score\":0,\"habit_score_effective\":100,\"tahfidz_score_effective\":0,\"attendance_rate\":0,\"total_attendance\":3,\"present_count\":0,\"punctuality_rate\":0,\"late_count\":0,\"sick_count\":0,\"permit_count\":0,\"alpha_count\":3,\"worship_total\":0,\"worship_hadir\":0,\"worship_ra